import numpy as np
import pandas as pd
from datetime import datetime, timedelta
import pytz

def r_time_update(time, updates=None, year=None, month=None, yday=None, 
                  mday=None, wday=None, hour=None, minute=None, second=None, 
                  tz=None, roll_month="preday", roll_dst=("boundary", "post"), 
                  week_start=1, exact=False):

    if time is None:
        return None

    # Convert input to pandas Series of Timestamps
    if isinstance(time, (str, datetime, pd.Timestamp)):
        time_arr = pd.to_datetime(pd.Series([time]))
    elif isinstance(time, np.ndarray):
        time_arr = pd.to_datetime(pd.Series(time))
    else:
        time_arr = pd.to_datetime(pd.Series(time))

    if len(time_arr) == 0:
        return time

    # Track if input was 'Date'
    is_date_input = False
    if isinstance(time, np.ndarray) and (time.dtype == 'datetime64[D]' or 'datetime' not in str(time.dtype)):
        is_date_input = True
    elif isinstance(time, str) and len(time) == 10: 
        is_date_input = True

    # Merge updates
    final_updates = {}
    if updates is not None:
        if isinstance(updates, dict):
            final_updates = updates.copy()
        elif isinstance(updates, list): # Handle case where updates is a list of values without names
            final_updates = {}

    updts_named = {
        'year': year, 'month': month, 'yday': yday, 'mday': mday, 
        'wday': wday, 'hour': hour, 'minute': minute, 'second': second
    }

    for nm, val in updts_named.items():
        if val is not None:
            if nm not in final_updates or final_updates[nm] is None:
                final_updates[nm] = val
            else:
                final_updates[nm] = final_updates[nm] + val

    # R's time_update: if tz is provided, it sets the timezone for the update operation.
    # If no tz is provided, it uses the timezone of the input time.
    target_tz_name = tz if tz is not None else "UTC"
    target_tz = pytz.timezone(target_tz_name)

    results = []
    for ts in time_arr:
        if pd.isna(ts):
            results.append(pd.NaT)
            continue

        # Work with the "wall clock" time in the target timezone
        if ts.tz is None:
            dt_local = ts.tz_localize('UTC').tz_convert(target_tz)
        else:
            dt_local = ts.tz_convert(target_tz)

        y, m, d = dt_local.year, dt_local.month, dt_local.day
        h, mi, s = dt_local.hour, dt_local.minute, dt_local.second

        # Apply absolute updates (overriding)
        if 'year' in final_updates: y = int(final_updates['year'])
        if 'month' in final_updates: m = int(final_updates['month'])
        if 'mday' in final_updates: d = int(final_updates['mday'])
        if 'hour' in final_updates: h = int(final_updates['hour'])
        if 'minute' in final_updates: mi = int(final_updates['minute'])
        if 'second' in final_updates: s = int(final_updates['second'])

        if 'yday' in final_updates:
            # yday is 1-based day of year
            base_date = datetime(y, 1, 1)
            res_date = base_date + timedelta(days=int(final_updates['yday']) - 1)
            m, d = res_date.month, res_date.day

        # Month overflow/underflow (R's date arithmetic)
        # 13th month becomes 1st month of next year
        month_idx = m - 1
        y += month_idx // 12
        m = (month_idx % 12) + 1

        # Day overflow/underflow
        # In R, time_update handles day overflow by rolling based on roll_month
        if m == 12:
            next_month_start = datetime(y + 1, 1, 1)
        else:
            next_month_start = datetime(y, m + 1, 1)

        last_day_of_month = (next_month_start - timedelta(days=1)).day

        if d > last_day_of_month:
            if roll_month == "preday":
                d = last_day_of_month
            else: # "post" or others: roll into next month(s)
                base_date = datetime(y, m, 1)
                res_date = base_date + timedelta(days=d - 1)
                y, m, d = res_date.year, res_date.month, res_date.day
        elif d < 1:
            # Roll backwards
            base_date = datetime(y, m, 1)
            res_date = base_date + timedelta(days=d - 1)
            y, m, d = res_date.year, res_date.month, res_date.day

        try:
            final_dt = datetime(y, m, d, h, mi, s)
            localized_dt = target_tz.localize(final_dt)
            results.append(localized_dt)
        except:
            results.append(pd.NaT)

    # Determine return type
    time_updated = any(k in final_updates for k in ['hour', 'minute', 'second']) or (tz is not None)

    if not time_updated and is_date_input:
        # Return Date: numpy array of datetime64[D]
        return np.array([pd.Timestamp(x).date() if pd.notna(x) else np.datetime64('NaT') for x in results], dtype='datetime64[D]')
    else:
        # Return POSIXct: pandas timestamps in UTC
        out = []
        for x in results:
            if pd.isna(x):
                out.append(pd.NaT)
            else:
                out.append(pd.Timestamp(x).tz_convert('UTC'))
        return np.array(out)
